examples.code:
cf create-service auditlog premium my-auditlog -c '{
  "xs-security": {
    "xsappname": "<unique name>",
    "oauth2-configuration": {
      "credential-types": ["x509"],
      "grant-types": ["client_credentials"]
    }
  }
}'

cf create-service-key my-auditlog my-auditlog-key -c '{
  "xsuaa": {
    "credential-type": "x509",
    "x509": { "key-length": 2048, "validity": 30, "validity-type": "DAYS" }
  }
}'

cf create-service auditlog-management default my-auditlog-mgmt -c '{
  "xs-security": {
    "xsappname": "<unique name>",
    "oauth2-configuration": { "credential-types": ["x509"], "grant-types": ["client_credentials"] }
  }
}'
cf create-service-key my-auditlog-mgmt my-key -c '{"xsuaa": {"credential-type": "x509", "x509": {"key-length": 2048, "validity": 1, "validity-type": "DAYS"}}}'

# last 30 days
GET <url>/auditlog/v2/auditlogrecords
# a time range and categories
GET <url>/auditlog/v2/auditlogrecords?time_from=2018-05-11T10:42:00&time_to=2018-05-12T10:42:00&category=audit.data-access,audit.configuration
# next chunk
GET <url>/auditlog/v2/auditlogrecords?handle=<handle from the previous response>
